import hashlib

def run(c,root,args):
 c.group='contracts-bounds';pub=root/'labs/api_depth/contracts';private=root/'assessor/api_depth/contracts';source=private/'bounds.c';api=root/'assessor/api_depth/api_depth.c';foundation=root/'assessor/foundations/foundation.c';common=['-std=c17','-Wall','-Wextra','-Werror','-I'+str(pub),'-I'+str(root/'labs/api_depth/include'),'-I'+str(root/'labs/foundations/include')]
 for cc in ('gcc','clang'):
  for name,flags in [('debug',['-O0']),('release',['-O2']),('sanitize',['-O1','-fsanitize=address,undefined','-fno-pie','-no-pie'])]:
   for trace,defines in [('instrumented',[]),('silent',['-DNDEBUG','-DAC_TRACE_ENABLED=0'])]:
    exe=c.root/(cc+'-'+name+'-'+trace+'-bounds');c.run([cc,*common,*flags,*defines,pub/'bounds_tests.c',source,api,foundation,'-o',exe]);text=c.run([exe],contains='BOUNDS-PASS:histories=65536;append_cases=18513;');c.require('host_CHAR_BIT=8;model_unit_bits=16' in text,'explicit host/model distinction '+cc+'-'+name+'-'+trace,text)
 for name,flag,selected,extra in [('bounds-wrap','AC_MUTANT_WRAP',source,[]),('bounds-sentinel','AC_MUTANT_SENTINEL',source,[]),('bounds-assert','AC_MUTANT_ASSERT',source,['-DNDEBUG']),('bounds-learner','UNSOLVED',pub/'bounds.c',[])]:
  exe=c.root/name;c.run(['gcc',*common,'-O2','-D'+flag,*extra,pub/'bounds_tests.c',selected,api,foundation,'-o',exe]);c.run([exe],expected=1,contains='BOUNDS-CHECK:')
 # Python's unbounded absolute time is independent of the C modular subtraction.
 rows=[];expected=[]
 for start in range(256):
  for elapsed in range(256):
   duration=(31*start+elapsed)%129;rows.append(f'{start} {duration} {elapsed}\n');expected.append('1 77' if not 1<=duration<=127 or elapsed>127 else f'0 {int(start+elapsed>=start+duration)}')
 data=c.write('deadline-oracle.txt',''.join(rows));digest=hashlib.sha256(data.read_bytes()).hexdigest()
 for cc in ('gcc','clang'):
  exe=c.root/(cc+'-bounds-oracle');c.run([cc,*common,'-O2',private/'bounds_oracle.c',source,api,foundation,'-o',exe]);actual=c.run([exe,data]).splitlines();c.require(actual==expected,'independent absolute-time oracle '+cc,dict(cases=len(rows),input_sha256=digest,model='absolute unbounded integer time versus bounded modular C;128+elapsed refused'))
 exe=c.root/'bounds-service';c.run(['gcc',*common,'-O2',private/'bounds_service.c',source,api,foundation,'-o',exe])
 for name,status,exitcode in [('capacity',2,0),('external',1,0),('internal',6,70)]:c.run([exe,name],expected=exitcode,contains='status='+str(status))
 # These are actual producer relocations before final section collection.
 obj=c.root/'bounds.o';c.run(['gcc',*common,'-O0','-c',source,'-o',obj]);undefined=c.run(['nm','-u',obj]);c.require('f_append' in undefined,'actual original append provider imported',undefined)
 for key,ordinary,changed in [('01.a','Typed byte-view admission and -infinite/zero-poll/positive-ms partition with output preservation','Tagged 8-bit counter deadline,127-tick horizon,65536 independent absolute-time cases plus65536 C histories'),('01.c','Actual CHAR_BIT/sizeof/type manifest and checked two-octet decoding per numeric16-bit unit','Explicit16-bit-unit simulation leaves host CHAR_BIT=8; rejects inadequate octet capacity before commit'),('02.a','Actual api_append18513 length/capacity/extent cases with independent expected prefix and unchanged failures,empty and SIZE_MAX','Actual f_append imported for future-destination aliasing with staging and epoch policy'),('02.b','Actual baseline whole-object overlap detector uses only byte-address equality; no unrelated-pointer order','Same-owner offset contract rejects identity overlap in constant admission work and copies disjoint bytes without repeating quadratic scan'),('07.a','Status/output and tagged lookup preserve identical found0/null/missing/backend semantics; actual object sizes recorded','Partial progress is a product of terminal status,consumed andproduced counts with failed prefix observable'),('07.b','Atomic copy validates beforecommit and compares preserve-output versus initialize-count-on-failure policies','Prefix parser publishes exactly counted prior bytes on malformed next octet or capacity exhaustion'),('07.c','Concrete found0 and found-null remain success;missing/backend distinct, sentinel mutant rejected','Reasoning packet quantifies excluded zero/null value and old-consumer migration rather than pretending a narrowed domain is equivalent'),('09.a','Compile-time octet premise,runtime wire rejection,internal assertion and test evidence remain separate','Attacker-controlled length/capacity enters through a checked parser and fails before internal object construction'),('09.b','Required evaluation counter and state mutation preserved across NDEBUG in12profiles; assertion-side-effect mutant rejected','Disabled instrumentation macro evaluates its optional argument zero times; required validation remains active'),('09.c','Capacity/external malformed/internal invariant have three explicit statuses and unchanged failed state','Actual original service-child exits70 only for internal fault; recoverable statuses remain distinct without host termination')]:
  c.observe('T18.'+key,ordinary,['contracts-bounds']);c.observe('T18.'+key,changed,['contracts-bounds'],True)
